/**
 * Typed access to the Rust core. All commands are generated by tauri-specta into
 * `bindings.ts`; this module adds friendlier type aliases and error helpers.
 */
import { listen, type UnlistenFn } from '@tauri-apps/api/event';

import type * as B from './bindings';

export { commands } from './bindings';

