/** `true` when running inside the Tauri webview (as opposed to a plain browser). */
export function isTauri(): boolean {
  return typeof window !== 'undefined' && '__TAURI_INTERNALS__' in window;
}

export function isCmdError(e: unknown): e is CmdError {
  return (
    typeof e === 'object' &&
    e !== null &&
    'code' in e &&
    'message' in e &&
    typeof (e as { message: unknown }).message === 'string'
  );
}

/** Converts any thrown value into a user-presentable message. */
export function errorMessage(e: unknown): string {
  if (isCmdError(e)) return e.message;
  if (e instanceof Error) return e.message;
  if (typeof e === 'string') return e;
  return 'Unexpected error';
}

export const VAULT_CHANGED = 'vault://changed';

export interface VaultChanged {
  kind: string;
}

/** Subscribes to vault change notifications emitted by the core. */
export async function onVaultChanged(cb: (e: VaultChanged) => void): Promise<UnlistenFn> {
  return listen<VaultChanged>(VAULT_CHANGED, (event) => {
    cb(event.payload);
  });
}

/** Generates a UUIDv7-style id on the client (used for new entities before saving). */
export function newId(): string {
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  const ts = BigInt(Date.now());
  for (let i = 0; i < 6; i++) {
    bytes[i] = Number((ts >> BigInt(8 * (5 - i))) & 0xffn);
  }
  bytes[6] = ((bytes[6] ?? 0) & 0x0f) | 0x70;
  bytes[8] = ((bytes[8] ?? 0) & 0x3f) | 0x80;
  const hex = Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

/** A sparse configuration with nothing set (everything inherited). */
export function emptyConfig(): HostConfig {
  return {
    ssh: {
      enabled: null,
      port: null,
      credential: null,
      jumpChain: null,
      proxy: null,
      agentForwarding: null,
      agentConfirm: null,
      env: null,
      startupSnippet: null,
      keepaliveSecs: null,
      compression: null,
      legacyAlgorithms: null,
      postQuantum: null,
      hostKeyPolicy: null,
      x11Forwarding: null,
      connectTimeoutSecs: null,
    },
    mosh: { enabled: null, serverCommand: null },
    telnet: { enabled: null, port: null, username: null, password: null },
    terminal: {
      theme: null,
      fontFamily: null,
      fontSize: null,
      backspace: null,
      termType: null,
      encoding: null,
      scrollback: null,
      cursorBlink: null,
      brightBold: null,
    },
    sftp: { startPath: null, showHidden: null, followSymlinks: null },
  };
}
